import deindent from '../../utils/deindent';
import { escape, escapeTemplate, stringify } from '../../utils/stringify';
import fixAttributeCasing from '../../utils/fixAttributeCasing';
import addToSet from '../../utils/addToSet';
import Compiler from '../Compiler';
import Node from './shared/Node';
import Element from './Element';
import Text from './Text';
import Block from '../dom/Block';
import Expression from './shared/Expression';

export interface StyleProp {
	key: string;
	value: Node[];
}

export default class Attribute extends Node {
	type: 'Attribute';
	start: number;
	end: number;

	compiler: Compiler;
	parent: Element;
	name: string;
	isSpread: boolean;
	isTrue: boolean;
	isDynamic: boolean;
	isSynthetic: boolean;
	shouldCache: boolean;
	expression?: Expression;
	chunks: (Text | Expression)[];
	dependencies: Set<string>;

	constructor(compiler, parent, scope, info) {
		super(compiler, parent, scope, info);

		if (info.type === 'Spread') {
			this.name = null;
			this.isSpread = true;
			this.isTrue = false;
			this.isSynthetic = false;

			this.expression = new Expression(compiler, this, scope, info.expression);
			this.dependencies = this.expression.dependencies;
			this.chunks = null;

			this.isDynamic = true; // TODO not necessarily
			this.shouldCache = false; // TODO does this mean anything here?
		}

		else {
			this.name = info.name;
			this.isTrue = info.value === true;
			this.isSynthetic = info.synthetic;

